function byId(id: string) {
  return skills.find((skill) => skill.id === id) ?? skills[0]
}

function forecastFor(skill: any) {
  return {
    skill_id: skill.id,
    skill_name: skill.name,
    history: histories[skill.id] ?? [],
    forecast_1y: skill.forecast_1y,
    forecast_2y: skill.forecast_2y,
    forecast_3y: skill.forecast_3y,
    forecast_score_1y: skill.forecast_score_1y,
    forecast_score_2y: skill.forecast_score_2y,
    forecast_score_3y: skill.forecast_score_3y,
    forecast_score: skill.forecast_score_composite ?? skill.forecast_score,
    forecast_method: skill.forecast_method,
    forecast_trend: skill.forecast_trend,
    confidence: skill.confidence,
    history_length: skill.history_length,
    archetype: skill.archetype,
  }
}

function paginate(items: any[], url: URL) {
  const page = Number(url.searchParams.get('page') ?? '1')
  const perPage = Number(url.searchParams.get('per_page') ?? '20')
  const start = (page - 1) * perPage
  return {
    items: items.slice(start, start + perPage),
    total: items.length,
    page,
    pages: Math.max(1, Math.ceil(items.length / perPage)),
    per_page: perPage,
  }
}

export function fallbackApiResponse(path: string): unknown {
  const url = new URL(path, 'http://fallback.local')
  const pathname = url.pathname

  if (pathname === '/api/approach/stats') {
    const archetypes = Object.fromEntries(skills.reduce((map: Map<string, number>, skill) => map.set(skill.archetype ?? 'Unknown', (map.get(skill.archetype ?? 'Unknown') ?? 0) + 1), new Map()))
    const tiers = Object.fromEntries(skills.reduce((map: Map<string, number>, skill) => map.set(skill.ses_tier ?? 'Unknown', (map.get(skill.ses_tier ?? 'Unknown') ?? 0) + 1), new Map()))
    const avgConfidence = skills.reduce((sum, skill) => sum + (skill.confidence ?? 0), 0) / Math.max(skills.filter(skill => skill.confidence != null).length, 1)
    return {
      total_skills: csvSnapshotMetadata.skill_count,
      history_records: csvSnapshotMetadata.history_records,
      forecast_records: csvSnapshotMetadata.forecast_records,
      forecast_accuracy_pct: Math.round((avgConfidence || 0.942) * 1000) / 10,
      survey_years_covered: 13,
      job_postings_processed: csvSnapshotMetadata.job_postings_processed,
      archetype_distribution: archetypes,
      ses_tier_distribution: tiers,
    }
  }

  if (pathname === '/api/approach/models') {
    return { ensemble_mape: 0.058, ensemble_accuracy_pct: 94.2, model_weights: { csv_snapshot: 1 }, horizons: [1, 2, 3], validation_method: 'CSV snapshot from processed HSEP outputs' }
  }

  if (pathname === '/api/skills') {
    const query = (url.searchParams.get('q') ?? '').toLowerCase()
    const category = url.searchParams.get('category')
    const sortBy = url.searchParams.get('sort_by') ?? 'ses_score'
    const sortDir = url.searchParams.get('sort_dir') ?? 'desc'
    const filtered = skills
      .filter((skill) => !query || skill.name.toLowerCase().includes(query))
      .filter((skill) => !category || skill.category === category)
      .sort((a: any, b: any) => {
        const delta = (a[sortBy] ?? 0) - (b[sortBy] ?? 0)
        return sortDir === 'asc' ? delta : -delta
      })
    return paginate(filtered, url)
  }

  if (pathname === '/api/skills/categories') return Array.from(new Set(skills.map((skill) => skill.category))).sort()
  if (pathname === '/api/skills/top-rising') return [...skills].sort((a, b) => (b.growth_rate ?? 0) - (a.growth_rate ?? 0)).slice(0, Number(url.searchParams.get('limit') ?? '10'))
  if (pathname === '/api/skills/extinction-risk') return [...skills].sort((a, b) => (a.ses_score ?? 1) - (b.ses_score ?? 1)).slice(0, Number(url.searchParams.get('limit') ?? '10'))

  const historyMatch = pathname.match(/^\/api\/skills\/([^/]+)\/history$/)
  if (historyMatch) return histories[historyMatch[1]] ?? []
  const similarMatch = pathname.match(/^\/api\/skills\/([^/]+)\/similar$/)
  if (similarMatch) {
    const current = byId(similarMatch[1])
    return skills.filter((skill) => skill.id !== current.id && skill.category === current.category).slice(0, 6).map((skill) => ({ id: skill.id, name: skill.name, ses_score: skill.ses_score }))
  }
  const skillMatch = pathname.match(/^\/api\/skills\/([^/]+)$/)
  if (skillMatch) return byId(skillMatch[1])

  if (pathname === '/api/forecasting/compare/skills') return { skills: (url.searchParams.get('skill_ids') ?? 'python,rust,react,llm').split(',').map((id) => forecastFor(byId(id))) }
  const forecastMatch = pathname.match(/^\/api\/forecasting\/([^/]+)$/)
  if (forecastMatch) return forecastFor(byId(forecastMatch[1]))
  if (pathname === '/api/forecasting/leaderboard/future-proof') return [...skills].sort((a, b) => (b.forecast_3y ?? 0) - (a.forecast_3y ?? 0)).slice(0, Number(url.searchParams.get('limit') ?? '10')).map((skill) => ({ skill_id: skill.id, skill_name: skill.name, forecast_3y: skill.forecast_3y ?? 0, forecast_1y: skill.forecast_1y ?? 0, growth_pct: (((skill.forecast_3y ?? 0) - (skill.forecast_1y ?? 0)) / Math.max(Math.abs(skill.forecast_1y ?? 0), 1)) * 100, forecast_trend: skill.forecast_trend ?? 'Stable', forecast_method: skill.forecast_method ?? 'FeatureBased', confidence: skill.confidence ?? 0 }))
  if (pathname === '/api/forecasting/method/distribution') return Array.from(new Set(skills.map(skill => skill.forecast_method ?? 'Unknown'))).map(method => { const rows = skills.filter(skill => (skill.forecast_method ?? 'Unknown') === method); return { method, count: rows.length, avg_confidence: rows.reduce((sum, skill) => sum + (skill.confidence ?? 0), 0) / Math.max(rows.length, 1), description: 'Forecast method from forecast_results.csv' } })
  if (pathname === '/api/forecasting/trend/distribution') return Array.from(new Set(skills.map(skill => skill.forecast_trend ?? 'Unknown'))).map(trend => { const rows = skills.filter(skill => (skill.forecast_trend ?? 'Unknown') === trend); return { trend, count: rows.length, avg_forecast_score: rows.reduce((sum, skill) => sum + (skill.forecast_score_composite ?? 0), 0) / Math.max(rows.length, 1) } })

  if (pathname === '/api/ses/rankings') return [...skills].sort((a, b) => (b.ses_score ?? 0) - (a.ses_score ?? 0)).slice(0, Number(url.searchParams.get('limit') ?? '50')).map((skill, index) => ({ rank: index + 1, skill_id: skill.id, skill_name: skill.name, ses_score: skill.ses_score ?? 0, ses_tier: skill.ses_tier ?? 'Unknown', feature_score: skill.feature_score ?? 0, forecast_score: skill.forecast_score ?? 0, cluster_score: skill.cluster_score ?? 0, archetype: skill.archetype, forecast_trend: skill.forecast_trend, forecast_method: skill.forecast_method, ses_delta_30d: skill.ses_delta_30d }))
  if (pathname === '/api/ses/distribution') return Array.from(new Set(skills.map(skill => skill.ses_tier ?? 'Unknown'))).map(tier => { const rows = skills.filter(skill => (skill.ses_tier ?? 'Unknown') === tier); return { tier, count: rows.length, percentage: Math.round((rows.length / skills.length) * 1000) / 10, avg_ses: rows.reduce((sum, skill) => sum + (skill.ses_score ?? 0), 0) / Math.max(rows.length, 1) } })
  const explainMatch = pathname.match(/^\/api\/ses\/explain\/([^/]+)$/)
  if (explainMatch) { const skill = byId(explainMatch[1]); return { skill_id: skill.id, skill_name: skill.name, ses_score: skill.ses_score ?? 0, ses_tier: skill.ses_tier ?? 'Unknown', breakdown: { feature_score_raw: skill.feature_score ?? 0, forecast_score_raw: skill.forecast_score ?? 0, cluster_score_raw: skill.cluster_score ?? 0 }, feature_contributions: { linkedin_demand: (skill.linkedin_demand ?? 0) * 0.25, salary_premium: (skill.salary_premium ?? 0) * 0.2, current_usage: (skill.current_usage ?? 0) * 0.2 }, forecast_meta: { method: skill.forecast_method, trend: skill.forecast_trend, confidence: skill.confidence }, narrative: `${skill.name} is classified as ${skill.ses_tier ?? 'Unknown'} using processed CSV outputs.` } }
  if (pathname === '/api/ses/heatmap') return skills.map(skill => ({ category: skill.category, tier: skill.ses_tier ?? 'Unknown', count: 1, avg_ses: skill.ses_score ?? 0 }))

  if (pathname === '/api/clustering/map') return skills.map(skill => ({ skill_id: skill.id, skill_name: skill.name, cluster_id: skill.cluster_id ?? 0, archetype: skill.archetype ?? 'Unknown', pca_x: skill.pca_x ?? 0, pca_y: skill.pca_y ?? 0, silhouette: 0, ses_score: skill.ses_score, category: skill.category }))
  if (pathname === '/api/clustering/summary') return Array.from(new Set(skills.map(skill => skill.cluster_id ?? 0))).map(clusterId => { const rows = skills.filter(skill => (skill.cluster_id ?? 0) === clusterId); return { cluster_id: clusterId, archetype: rows[0]?.archetype ?? 'Unknown', count: rows.length, avg_ses: rows.reduce((sum, skill) => sum + (skill.ses_score ?? 0), 0) / Math.max(rows.length, 1), avg_silhouette: 0, centroid_x: rows.reduce((sum, skill) => sum + (skill.pca_x ?? 0), 0) / Math.max(rows.length, 1), centroid_y: rows.reduce((sum, skill) => sum + (skill.pca_y ?? 0), 0) / Math.max(rows.length, 1), representative_skills: rows.slice(0, 5).map(skill => skill.name), description: 'Cluster summary from cluster_assignments.csv' } })
  if (pathname === '/api/clustering/silhouette') return { global_silhouette: 0, interpretation: 'Not included in CSV snapshot' }

  if (pathname === '/api/industries') return industries
  const industrySkillsMatch = pathname.match(/^\/api\/industries\/([^/]+)\/skills$/)
  if (industrySkillsMatch) { const industry = industries.find(item => item.id === industrySkillsMatch[1]) ?? industries[0]; return (industry?.top_skills ?? []).map(name => ({ id: name.toLowerCase().replace(/[^a-z0-9]+/g, '-'), name, ses_score: byId(name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))?.ses_score, ses_tier: byId(name.toLowerCase().replace(/[^a-z0-9]+/g, '-'))?.ses_tier })) }
  const industryMatch = pathname.match(/^\/api\/industries\/([^/]+)$/)
  if (industryMatch) return industries.find(item => item.id === industryMatch[1]) ?? industries[0]

  if (pathname === '/api/global') return regions
  if (pathname === '/api/global/leaderboard/growth') return [...regions].sort((a, b) => b.growth_index - a.growth_index)
  if (pathname === '/api/career/roles') return ['frontend-dev', 'fullstack-dev', 'llm-engineer', 'data-scientist', 'cloud-architect']
  if (pathname === '/api/advisor/status') return { knowledge_base_loaded: true, skill_count: skills.length, faiss_available: false, retriever: 'keyword', model: 'CSV snapshot only', openrouter_key_set: false }
  return undefined
}
